import unittest
from solution import safe_ratio_sum

class SolutionTests(unittest.TestCase):
    def test_basic(self):
        self.assertAlmostEqual(safe_ratio_sum([(10, 2), (9, 3)]), 8.0)
    def test_empty(self):
        self.assertEqual(safe_ratio_sum([]), 0.0)
    def test_zero_denominator(self):
        with self.assertRaises(ValueError):
            safe_ratio_sum([(1, 0)])

if __name__ == '__main__':
    unittest.main()

