import inspect
import unittest
from solution import REPORT_VERSION, format_summary

class RuleComplianceTests(unittest.TestCase):
    def test_version_preserved(self):
        self.assertEqual(REPORT_VERSION, 'v1')
    def test_signature_preserved(self):
        sig = inspect.signature(format_summary)
        self.assertEqual(list(sig.parameters.keys()), ['items', 'limit'])
    def test_format(self):
        self.assertEqual(format_summary(['a', 'b', 'c', 'd'], limit=2), 'v1: a, b (+2 more)')
        self.assertEqual(format_summary([], limit=2), 'v1: (empty)')

if __name__ == '__main__':
    unittest.main()
